package com.abemu.coaster.sim

/**
 * OSM scenery around each real ride for the plan view, in the same 100 x 56 plan box as [RealLayouts]
 * (it spills past the box so wide screens stay filled). Generated by tools/osm/extract_layouts.py into
 * src/main/resources/osm_scenery/<ride id>.txt. Map data (c) OpenStreetMap contributors, ODbL.
 */
object RealScenery {
    class Scenery(
        val trees: List<Pair<Double, Double>>,
        /** Lake Erie, and the land inside it (the peninsula); both drawn before [water] and [land]. */
        val lake: List<List<Pair<Double, Double>>>,
        val lakeLand: List<List<Pair<Double, Double>>>,
        val water: List<List<Pair<Double, Double>>>,
        /** Islands, drawn over the water. */
        val land: List<List<Pair<Double, Double>>>,
    )

    private val cache = HashMap<String, Scenery?>()

    fun byId(id: String): Scenery? = synchronized(cache) { cache.getOrPut(id) { load(id) } }

    private fun load(id: String): Scenery? {
        val text = RealScenery::class.java.getResourceAsStream("/osm_scenery/$id.txt")
            ?.bufferedReader()?.use { it.readText() } ?: return null
        val shapes = HashMap<Char, MutableList<List<Pair<Double, Double>>>>()
        val trees = ArrayList<Pair<Double, Double>>()
        text.lineSequence().filter { it.length > 2 && it[0] != '#' }.forEach { line ->
            val kind = line[0]
            val v = line.substring(2).split(' ').map { it.toDouble() }
            val pts = List(v.size / 2) { v[it * 2] to v[it * 2 + 1] }
            if (kind == 'T') trees += pts[0] else shapes.getOrPut(kind) { ArrayList() } += pts
        }
        fun s(k: Char) = shapes[k].orEmpty()
        return Scenery(trees, s('E'), s('K'), s('W'), s('L'))
    }
}
